import sys

def main():
    import sys
    import collections

    input = sys.stdin.read().split()
    n = int(input[0])
    m = int(input[1])
    board = input[2:]

    def find_neighbors(x, y):
        if board[x][y] == 'U':
            return [(x + 1, y)]
        elif board[x][y] == 'D':
            return [(x - 1, y)]
        elif board[x][y] == 'L':
            return [(x, y + 1)]
        else:
            return [(x, y - 1)]

    def dfs(x, y, visited, group):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if (cx, cy) not in visited:
                visited.add((cx, cy))
                group.add((cx, cy))
                for nx, ny in find_neighbors(cx, cy):
                    if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited:
                        stack.append((nx, ny))

    groups = []
    visited = set()
    for i in range(n):
        for j in range(m):
            if (i, j) not in visited:
                group = set()
                dfs(i, j, visited, group)
                groups.append(group)

    distinct_photos = set()
    for i in range(n):
        for j in range(0, m, 2):
            free_cells = {(i, j), (i, j + 1)}
            remaining_groups = [group for group in groups if not free_cells.intersection(group)]
            connected_components = []
            visited = set()
            for x in range(n):
                for y in range(m):
                    if (x, y) not in visited and (x, y) not in free_cells:
                        component = set()
                        dfs(x, y, visited, component)
                        connected_components.append(component)
            photo = tuple(sorted(free_cells))
            distinct_photos.add(photo)

    print(len(distinct_photos))

if __name__ == "__main__":
    main()
